#!/usr/bin/env python3
import sys, os, csv, json, gzip, io, re
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    t = b.decode('utf-8-sig')
    return [l.rstrip('\r') for l in t.split('\n') if l.strip('\r \t') != '']


def csv_rows(lines, delim=','):
    return list(csv.reader(lines, delimiter=delim))


def epoch(sec):
    return int(sec)


def to_ts(dt):
    return int((dt - EPOCH).total_seconds())


def local_to_ts(naive, tz, fold):
    return to_ts(naive.replace(tzinfo=tz, fold=fold))


def iso_ts(s):
    s = s.strip()
    if s.endswith('Z') or s.endswith('z'):
        s = s[:-1] + '+00:00'
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return to_ts(dt.replace(microsecond=0))


def std_offset(tz, ts):
    dt = datetime.fromtimestamp(ts, tz)
    return dt.utcoffset() - (dt.dst() or timedelta(0))


def dirn(s):
    return 'IN' if s.strip().upper() in ('IN', 'I', 'K', 'CLOCK_IN') else 'OUT'


def parse_abbr(lines, tz, out):
    hdr = None
    for row in csv_rows(lines):
        if not row:
            continue
        r = [c.strip() for c in row]
        if 'Badge' in r and 'Punch' in r:
            hdr = {n: i for i, n in enumerate(r)}
            continue
        if hdr is None:
            continue
        g = lambda n: r[hdr[n]]
        d = datetime.strptime(g('Date'), '%m/%d/%Y')
        t = g('Time').upper()
        m = re.fullmatch(r'(\d{1,2}):(\d\d):(\d\d)\s*([AP]M)?', t)
        h, mi, s, ap = int(m[1]), int(m[2]), int(m[3]), m[4]
        if ap:
            h = h % 12 + (12 if ap == 'PM' else 0)
        naive = d.replace(hour=h, minute=mi, second=s)
        z = g('Zone').upper()
        fold = 1 if z.endswith('ST') else 0
        out.append((g('Record'), g('Badge'), dirn(g('Punch')), local_to_ts(naive, tz, fold)))


def parse_epoch(lines, tz, out):
    schema = 1
    for l in lines:
        o = json.loads(l)
        if set(o) == {'schema'}:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2 or 'punch_id' in o:
            ts = int(o['epoch_ms']) // 1000
            out.append((str(o['punch_id']), o['employee'], dirn(o['direction']), ts))
        else:
            if 'ts_ms' in o:
                ts = int(o['ts_ms']) // 1000
            else:
                ts = int(o['ts'])
            out.append((str(o['id']), o['emp'], dirn(o['dir']), ts))


def parse_offset(lines, tz, out):
    rows = csv_rows(lines, ';')
    hdr = {n.strip(): i for i, n in enumerate(rows[0])}
    for r in rows[1:]:
        g = lambda n: r[hdr[n]]
        out.append((g('punch_id'), g('employee'), dirn(g('event')), iso_ts(g('timestamp'))))


def parse_legacy(lines, tz, out):
    off = None
    for l in lines:
        t = l[:1]
        if t == 'H':
            m = re.match(r'([+-])(\d\d)(\d\d)', l[13:18])
            if m:
                v = int(m[2]) * 3600 + int(m[3]) * 60
                off = timedelta(seconds=-v if m[1] == '-' else v)
            else:
                off = None
        elif t == 'D':
            pid = l[1:9]
            badge = 'E' + l[9:15].strip()
            dr = dirn(l[15])
            n = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            guess = to_ts(n.replace(tzinfo=UTC))
            if off is None:
                o = std_offset(tz, guess)
                o = std_offset(tz, guess - int(o.total_seconds()))
            else:
                o = off
            out.append((pid, badge, dr, guess - int(o.total_seconds())))


def parse_de(lines, tz, out):
    hdr = None
    for l in lines:
        r = [c.strip() for c in l.split('\t')]
        if 'Ausweis' in r:
            hdr = {n: i for i, n in enumerate(r)}
            continue
        g = lambda n: r[hdr[n]]
        n = datetime.strptime(g('Datum') + ' ' + g('Uhrzeit'), '%d.%m.%Y %H:%M')
        fold = 1 if g('Zeitzone').upper() == 'MEZ' else 0
        out.append((g('Nr'), g('Ausweis'), dirn(g('Buchung')), local_to_ts(n, tz, fold)))


def parse_localcsv(lines, tz, out):
    rows = csv_rows(lines)
    hdr = {n.strip(): i for i, n in enumerate(rows[0])}
    for r in rows[1:]:
        g = lambda n: r[hdr[n]].strip()
        n = datetime.strptime(g('local_time'), '%Y-%m-%d %H:%M:%S')
        out.append((g('punch_ref'), g('employee_id'), dirn(g('direction')), local_to_ts(n, tz, 0)))


def parse_localjsonl(lines, tz, out):
    for l in lines:
        p = json.loads(l)['punch']
        n = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'], dirn(p['type']), local_to_ts(n, tz, 0)))


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}


def files_of(d):
    res = []
    for root, _, fs in os.walk(d):
        for f in fs:
            res.append(os.path.join(root, f))
    return sorted(res)


def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = iso_ts(period['corrections_cutoff'])
    sites = {}
    with open(os.path.join(inp, 'sites.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    emps = {}
    with open(os.path.join(inp, 'employees.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            emps[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    with open(os.path.join(inp, 'rates.csv'), encoding='utf-8-sig', newline='') as f:
        for r in csv.DictReader(f):
            rates.setdefault(r['employee_id'].strip(), []).append(
                (date.fromisoformat(r['effective_from'].strip()), Decimal(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    punches = {}  # (site,id) -> [emp, dir, ts]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for fp in files_of(d):
            out = []
            PARSERS[fmt](read_text(fp), tz, out)
            for pid, emp, dr, ts in out:
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = [emp.strip(), dr, ts]

    # corrections
    corr = []
    cd = os.path.join(inp, 'corrections')
    if os.path.isdir(cd):
        for fp in files_of(cd):
            lines = read_text(fp)
            if not lines:
                continue
            rows = csv_rows(lines)
            hdr = {n.strip(): i for i, n in enumerate(rows[0])}
            for r in rows[1:]:
                if not r:
                    continue
                c = {n: (r[i].strip() if i < len(r) else '') for n, i in hdr.items()}
                corr.append(c)
    corr = [c for c in corr if iso_ts(c['issued_at']) <= cutoff]
    corr.sort(key=lambda c: (iso_ts(c['issued_at']), c['correction_id']))
    applied = 0
    for c in corr:
        k = (c['site'], c['punch_id'])
        a = c['action'].strip().lower()
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = iso_ts(c['time'])
                applied += 1
        elif a == 'add':
            if k not in ever and c['site'] in sites:
                punches[k] = [c['employee'], dirn(c['type']), iso_ts(c['time'])]
                ever.add(k)
                applied += 1

    home_tz = {e: sites[s][0] for e, s in emps.items()}
    by_emp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in emps:
            by_emp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, tz):
        off = int(datetime.fromtimestamp(ts, tz).utcoffset().total_seconds())
        loc = ts + off
        return (loc + 180) // 360 * 360 - off

    def wday(ts, emp):
        return datetime.fromtimestamp(ts, home_tz[emp]).date()

    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    result = {}
    night_cache = {}

    def night_minutes(a, b, tz):
        key = id(tz)
        d0 = datetime.fromtimestamp(a, tz).date() - timedelta(days=1)
        d1 = datetime.fromtimestamp(b, tz).date()
        tot = 0
        d = d0
        while d <= d1:
            s = local_to_ts(datetime(d.year, d.month, d.day, 22), tz, 0)
            n = d + timedelta(days=1)
            e = local_to_ts(datetime(n.year, n.month, n.day, 6), tz, 0)
            lo, hi = max(a, s), min(b, e)
            if hi > lo:
                tot += hi - lo
            d = n
        return tot // 60

    for emp in emps:
        pl = sorted(by_emp.get(emp, []))
        kept = []
        for p in pl:
            if kept and kept[-1][4] == p[4] and p[0] - kept[-1][0] <= 300:
                r = rnd(p[0], sites[p[2]][0])
                if pstart <= wday(r, emp) <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            kept.append(p)
        rk = [(rnd(p[0], sites[p[2]][0]), p) for p in kept]
        shifts = []
        i = 0
        n = len(rk)
        while i < n:
            r, p = rk[i]
            if p[4] == 'IN':
                if i + 1 < n and rk[i + 1][1][4] == 'OUT' and rk[i + 1][0] - r <= 16 * 3600:
                    shifts.append((r, rk[i + 1][0], p[2]))
                    i += 2
                    continue
                if pstart <= wday(r, emp) <= pend:
                    exc['open_shifts'] += 1
            else:
                if pstart <= wday(r, emp) <= pend:
                    exc['orphan_outs'] += 1
            i += 1
        shifts.sort()
        rows = []
        for a, b, site in shifts:
            wd = wday(a, emp)
            if not (pstart <= wd <= pend):
                continue
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(a, b, sites[site][0]), paid)
            rows.append([wd, paid, night, 0])
        # overtime
        daily = {}
        weekly = {}
        for r in rows:
            wd, paid = r[0], r[1]
            before = daily.get(wd, 0)
            daily[wd] = before + paid
            dot = max(0, before + paid - 480) - max(0, before - 480)
            nd = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wb = weekly.get(wk, 0)
            weekly[wk] = wb + nd
            wot = max(0, wb + nd - 2400) - max(0, wb - 2400)
            r[3] = dot + wot
        gross = Fraction(0)
        for wd, paid, night, ot in rows:
            rate = None
            for ef, rt in rates.get(emp, []):
                if ef <= wd:
                    rate = rt
            rate = Fraction(rate or 0)
            gross += rate * (Fraction(paid - ot) + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
        cents = (gross * 100 + Fraction(1, 2)).__floor__()
        result[emp] = {
            'shifts': len(rows), 'paid_minutes': sum(r[1] for r in rows),
            'overtime_minutes': sum(r[3] for r in rows), 'night_minutes': sum(r[2] for r in rows),
            'gross': '%d.%02d' % divmod(cents, 100)}
    tot = {k: sum(v[k] for v in result.values()) for k in
           ('shifts', 'paid_minutes', 'overtime_minutes', 'night_minutes')}
    tc = sum(int(v['gross'].replace('.', '')) for v in result.values())
    tot['gross'] = '%d.%02d' % divmod(tc, 100)
    with open(outp, 'w') as f:
        json.dump({'period': {'start': period['start'], 'end': period['end']},
                   'employees': result, 'exceptions': exc, 'totals': tot}, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
